'use strict';
const express=require('express'),path=require('path'),{createEngine}=require('../codeAssistant.cjs'),config=require('../codeAssistantConfig.cjs'),provider=require('../codeAssistantProvider.cjs');
const router=express.Router();router.use((req,res,next)=>{const port=String(process.env.PORT||3001),origin=req.get('origin');if(!['127.0.0.1','::1','::ffff:127.0.0.1'].includes(req.socket.remoteAddress)||(origin&&!['http://localhost:'+port,'http://127.0.0.1:'+port].includes(origin)))return res.status(403).json({error:'Trợ lý code chỉ dùng trong app trên máy này'});if(!['GET','HEAD'].includes(req.method)&&!req.is('application/json'))return res.status(415).json({error:'Yêu cầu JSON'});next()});
const engine=createEngine({dataDir:path.join(require('../paths').DATA_DIR,'code-assistant'),provider:provider.createProvider(),config});
const handle=fn=>async(req,res)=>{try{const result=await fn(req,res);if(!res.headersSent)res.json(result)}catch(e){res.status(e.status||400).json({error:e.message})}};
router.get('/config',handle(()=>({provider:'MUSE',...provider.configured(),defaultProject:engine.projects().find(p=>p.self),buildMuse:true})));
router.get('/projects',handle(()=>engine.projects()));router.post('/projects',handle(req=>engine.open(req.body.root)));
router.get('/projects/:id/tree',handle(req=>engine.tree(req.params.id)));router.get('/projects/:id/file',handle(req=>engine.file(req.params.id,req.query.path)));
router.get('/projects/:id/sessions',handle(req=>engine.sessions(req.params.id)));router.get('/projects/:id/tasks',handle(req=>engine.tasks(req.params.id)));
router.post('/projects/:id/chat',handle(async(req,res)=>{if(!provider.configured().configured)throw Error('Kết nối tài khoản MUSE trong Cài đặt trước');const t=await engine.chat(req.params.id,req.body);res.status(202);return t}));router.get('/tasks/:id',handle(req=>engine.task(req.params.id)));router.post('/tasks/:id/cancel',handle(req=>engine.cancel(req.params.id)));
router.get('/proposals/:id',handle(req=>engine.proposal(req.params.id)));
router.post('/proposals/:id/apply',handle(req=>engine.apply(req.params.id)));router.post('/proposals/:id/undo',handle(req=>engine.undo(req.params.id)));
router.post('/projects/:id/run',handle((req,res)=>{res.status(202);return engine.run(req.params.id,req.body.script)}));
let builder;function builds(){return builder||(builder=require('../codeAssistantBuild.cjs').createBuilder({config,dataDir:path.join(require('../paths').DATA_DIR,'code-assistant'),engine}))}
router.post('/projects/:id/build-muse',handle((req,res)=>{res.status(202);return builds().build(req.params.id)}));router.get('/deployments',handle(()=>builds().list()));router.post('/deployments/:id/activate',handle(req=>builds().activate(req.params.id)));router.post('/deployments/:id/rollback',handle(req=>builds().rollback(req.params.id)));
router.get('/recovery',handle((req,res)=>{res.type('html').send('<!doctype html><meta charset="utf-8"><title>Khôi phục MUSE</title><style>body{font:16px system-ui;background:#18181b;color:#eee;max-width:700px;margin:60px auto}button{padding:12px;margin:10px}</style><h1>Khôi phục giao diện MUSE</h1><p>Bản mã nguồn vẫn được giữ. Chọn bản đã nạp để trở về giao diện trước đó.</p><div id="items"></div><script>fetch("/api/code-assistant/deployments").then(r=>r.json()).then(rows=>{for(const d of rows.filter(x=>x.status==="active")){const b=document.createElement("button");b.textContent="Khôi phục bản trước "+new Date(d.createdAt).toLocaleString();b.onclick=()=>fetch("/api/code-assistant/deployments/"+d.id+"/rollback",{method:"POST",headers:{"Content-Type":"application/json"},body:"{}"}).then(r=>r.json()).then(x=>{if(x.error)alert(x.error);else location.href="/"});document.querySelector("#items").append(b)}})</script>') }));
module.exports=router;
